export interface Product {
  id: string;
  name: string;
  price: number;
  currency: string;
  quantity: number;
  metadata?: Record<string, unknown>;
}

export interface CartItem extends Product {
  addedAt: Date;
  updatedAt: Date;
}

export interface Cart {
  id: string;
  items: CartItem[];
  createdAt: Date;
  updatedAt: Date;
  metadata?: Record<string, unknown>;
}

export interface AddItemInput {
  productId: string;
  name: string;
  price: number;
  currency: string;
  quantity: number;
  metadata?: Record<string, unknown>;
}

export interface UpdateItemInput {
  productId: string;
  quantity: number;
}

export interface CartEvent {
  type: CartEventType;
  cartId: string;
  timestamp: Date;
  payload: unknown;
}

export type CartEventType =
  | 'cart.created'
  | 'cart.updated'
  | 'cart.cleared'
  | 'item.added'
  | 'item.updated'
  | 'item.removed'
  | 'item.quantityChanged';

export interface StorageAdapter {
  get(cartId: string): Promise<Cart | null>;
  set(cart: Cart): Promise<void>;
  delete(cartId: string): Promise<void>;
  exists(cartId: string): Promise<boolean>;
}

export interface CartOptions {
  storage: StorageAdapter;
  eventBus?: EventBus;
  maxItems?: number;
  maxQuantityPerItem?: number;
}

export interface EventBus {
  publish(event: CartEvent): Promise<void>;
  subscribe(eventType: CartEventType, handler: EventHandler): void;
  unsubscribe(eventType: CartEventType, handler: EventHandler): void;
}

export type EventHandler = (event: CartEvent) => Promise<void> | void;

export interface CartSummary {
  itemCount: number;
  totalQuantity: number;
  subtotal: number;
  currency: string;
}

import { EventBus, CartEvent, CartEventType, EventHandler } from './types';

export class InMemoryEventBus implements EventBus {
  private handlers: Map<CartEventType, Set<EventHandler>> = new Map();

  async publish(event: CartEvent): Promise<void> {
    const handlers = this.handlers.get(event.type);
    if (handlers) {
      await Promise.all(
        Array.from(handlers).map((handler) => handler(event))
      );
    }
  }

  subscribe(eventType: CartEventType, handler: EventHandler): void {
    if (!this.handlers.has(eventType)) {
      this.handlers.set(eventType, new Set());
    }
    this.handlers.get(eventType)!.add(handler);
  }

  unsubscribe(eventType: CartEventType, handler: EventHandler): void {
    const handlers = this.handlers.get(eventType);
    if (handlers) {
      handlers.delete(handler);
    }
  }
}

export class AsyncEventBus implements EventBus {
  private handlers: Map<CartEventType, Set<EventHandler>> = new Map();
  private queue: CartEvent[] = [];
  private processing = false;

  async publish(event: CartEvent): Promise<void> {
    this.queue.push(event);
    if (!this.processing) {
      this.processQueue();
    }
  }

  private async processQueue(): Promise<void> {
    this.processing = true;
    while (this.queue.length > 0) {
      const event = this.queue.shift()!;
      const handlers = this.handlers.get(event.type);
      if (handlers) {
        await Promise.allSettled(
          Array.from(handlers).map((handler) => handler(event))
        );
      }
    }
    this.processing = false;
  }

  subscribe(eventType: CartEventType, handler: EventHandler): void {
    if (!this.handlers.has(eventType)) {
      this.handlers.set(eventType, new Set());
    }
    this.handlers.get(eventType)!.add(handler);
  }

  unsubscribe(eventType: CartEventType, handler: EventHandler): void {
    const handlers = this.handlers.get(eventType);
    if (handlers) {
      handlers.delete(handler);
    }
  }
}

import { StorageAdapter, Cart } from './types';
import * as fs from 'fs/promises';
import * as path from 'path';

export class InMemoryStorage implements StorageAdapter {
  private store: Map<string, Cart> = new Map();

  async get(cartId: string): Promise<Cart | null> {
    return this.store.get(cartId) ?? null;
  }

  async set(cart: Cart): Promise<void> {
    this.store.set(cart.id, { ...cart });
  }

  async delete(cartId: string): Promise<void> {
    this.store.delete(cartId);
  }

  async exists(cartId: string): Promise<boolean> {
    return this.store.has(cartId);
  }

  clear(): void {
    this.store.clear();
  }

  size(): number {
    return this.store.size;
  }
}

export class FileStorage implements StorageAdapter {
  private directory: string;

  constructor(directory: string = './data/carts') {
    this.directory = directory;
  }

  private getFilePath(cartId: string): string {
    return path.join(this.directory, `${cartId}.json`);
  }

  async initialize(): Promise<void> {
    try {
      await fs.mkdir(this.directory, { recursive: true });
    } catch {
      // Directory might already exist
    }
  }

  async get(cartId: string): Promise<Cart | null> {
    try {
      const filePath = this.getFilePath(cartId);
      const data = await fs.readFile(filePath, 'utf-8');
      const cart = JSON.parse(data);
      return {
        ...cart,
        createdAt: new Date(cart.createdAt),
        updatedAt: new Date(cart.updatedAt),
        items: cart.items.map((item: any) => ({
          ...item,
          addedAt: new Date(item.addedAt),
          updatedAt: new Date(item.updatedAt),
        })),
      };
    } catch {
      return null;
    }
  }

  async set(cart: Cart): Promise<void> {
    await this.initialize();
    const filePath = this.getFilePath(cart.id);
    const data = JSON.stringify(cart, null, 2);
    await fs.writeFile(filePath, data, 'utf-8');
  }

  async delete(cartId: string): Promise<void> {
    try {
      const filePath = this.getFilePath(cartId);
      await fs.unlink(filePath);
    } catch {
      // File might not exist
    }
  }

  async exists(cartId: string): Promise<boolean> {
    try {
      const filePath = this.getFilePath(cartId);
      await fs.access(filePath);
      return true;
    } catch {
      return false;
    }
  }
}

export class RedisStorage implements StorageAdapter {
  private client: any;
  private keyPrefix: string;

  constructor(client: any, keyPrefix: string = 'cart:') {
    this.client = client;
    this.keyPrefix = keyPrefix;
  }

  private getKey(cartId: string): string {
    return `${this.keyPrefix}${cartId}`;
  }

  async get(cartId: string): Promise<Cart | null> {
    const data = await this.client.get(this.getKey(cartId));
    if (!data) return null;
    const cart = JSON.parse(data);
    return {
      ...cart,
      createdAt: new Date(cart.createdAt),
      updatedAt: new Date(cart.updatedAt),
      items: cart.items.map((item: any) => ({
        ...item,
        addedAt: new Date(item.addedAt),
        updatedAt: new Date(item.updatedAt),
      })),
    };
  }

  async set(cart: Cart): Promise<void> {
    const data = JSON.stringify(cart);
    await this.client.set(this.getKey(cart.id), data);
  }

  async delete(cartId: string): Promise<void> {
    await this.client.del(this.getKey(cartId));
  }

  async exists(cartId: string): Promise<boolean> {
    return (await this.client.exists(this.getKey(cartId))) === 1;
  }
}

import {
  Cart,
  CartItem,
  AddItemInput,
  UpdateItemInput,
  CartOptions,
  CartEvent,
  CartEventType,
  CartSummary,
  Product,
} from './types';
import { InMemoryEventBus } from './event-bus';
import { InMemoryStorage } from './storage';

export class CartService {
  private storage: CartOptions['storage'];
  private eventBus: CartOptions['eventBus'];
  private maxItems: number;
  private maxQuantityPerItem: number;

  constructor(options: CartOptions) {
    this.storage = options.storage;
    this.eventBus = options.eventBus ?? new InMemoryEventBus();
    this.maxItems = options.maxItems ?? 100;
    this.maxQuantityPerItem = options.maxQuantityPerItem ?? 999;
  }

  async createCart(cartId: string, metadata?: Record<string, unknown>): Promise<Cart> {
    const now = new Date();
    const cart: Cart = {
      id: cartId,
      items: [],
      createdAt: now,
      updatedAt: now,
      metadata,
    };

    await this.storage.set(cart);
    await this.emitEvent({
      type: 'cart.created',
      cartId,
      timestamp: now,
      payload: { cart },
    });

    return cart;
  }

  async getCart(cartId: string): Promise<Cart | null> {
    return this.storage.get(cartId);
  }

  async addItem(cartId: string, input: AddItemInput): Promise<Cart> {
    const cart = await this.getOrCreateCart(cartId);
    this.validateAddItem(cart, input);

    const existingItemIndex = cart.items.findIndex(
      (item) => item.productId === input.productId
    );

    const now = new Date();

    if (existingItemIndex >= 0) {
      const item = cart.items[existingItemIndex];
      const newQuantity = item.quantity + input.quantity;
      this.validateQuantity(newQuantity);

      item.quantity = newQuantity;
      item.updatedAt = now;
      item.price = input.price;
      item.metadata = { ...item.metadata, ...input.metadata };
    } else {
      if (cart.items.length >= this.maxItems) {
        throw new Error(`Maximum number of items (${this.maxItems}) reached`);
      }

      const newItem: CartItem = {
        productId: input.productId,
        name: input.name,
        price: input.price,
        currency: input.currency,
        quantity: input.quantity,
        metadata: input.metadata,
        addedAt: now,
        updatedAt: now,
      };
      cart.items.push(newItem);
    }

    cart.updatedAt = now;
    await this.storage.set(cart);

    await this.emitEvent({
      type: existingItemIndex >= 0 ? 'item.updated' : 'item.added',
      cartId,
      timestamp: now,
      payload: { productId: input.productId, quantity: input.quantity },
    });

    await this.emitEvent({
      type: 'cart.updated',
      cartId,
      timestamp: now,
      payload: { cart },
    });

    return cart;
  }

  async updateItem(cartId: string, input: UpdateItemInput): Promise<Cart> {
    const cart = await this.getCartOrThrow(cartId);
    const itemIndex = cart.items.findIndex(
      (item) => item.productId === input.productId
    );

    if (itemIndex === -1) {
      throw new Error(`Item with productId ${input.productId} not found`);
    }

    this.validateQuantity(input.quantity);

    const now = new Date();
    const item = cart.items[itemIndex];

    if (input.quantity === 0) {
      cart.items.splice(itemIndex, 1);
      await this.emitEvent({
        type: 'item.removed',
        cartId,
        timestamp: now,
        payload: { productId: input.productId },
      });
    } else {
      item.quantity = input.quantity;
      item.updatedAt = now;
      await this.emitEvent({
        type: 'item.quantityChanged',
        cartId,
        timestamp: now,
        payload: { productId: input.productId, quantity: input.quantity },
      });
    }

    cart.updatedAt = now;
    await this.storage.set(cart);

    await this.emitEvent({
      type: 'cart.updated',
      cartId,
      timestamp: now,
      payload: { cart },
    });

    return cart;
  }

  async removeItem(cartId: string, productId: string): Promise<Cart> {
    const cart = await this.getCartOrThrow(cartId);
    const itemIndex = cart.items.findIndex((item) => item.productId === productId);

    if (itemIndex === -1) {
      throw new Error(`Item with productId ${productId} not found`);
    }

    const now = new Date();
    cart.items.splice(itemIndex, 1);
    cart.updatedAt = now;
    await this.storage.set(cart);

    await this.emitEvent({
      type: 'item.removed',
      cartId,
      timestamp: now,
      payload: { productId },
    });

    await this.emitEvent({
      type: 'cart.updated',
      cartId,
      timestamp: now,
      payload: { cart },
    });

    return cart;
  }

  async clearCart(cartId: string): Promise<Cart> {
    const cart = await this.getCartOrThrow(cartId);
    const now = new Date();
    cart.items = [];
    cart.updatedAt = now;
    await this.storage.set(cart);

    await this.emitEvent({
      type: 'cart.cleared',
      cartId,
      timestamp: now,
      payload: { previousItemCount: cart.items.length },
    });

    await this.emitEvent({
      type: 'cart.updated',
      cartId,
      timestamp: now,
      payload: { cart },
    });

    return cart;
  }

  async deleteCart(cartId: string): Promise<void> {
    await this.storage.delete(cartId);
  }

  getSummary(cart: Cart): CartSummary {
    const itemCount = cart.items.length;
    const totalQuantity = cart.items.reduce((sum, item) => sum + item.quantity, 0);
    const subtotal = cart.items.reduce(
      (sum, item) => sum + item.price * item.quantity,
      0
    );
    const currency = cart.items[0]?.currency ?? 'USD';

    return {
      itemCount,
      totalQuantity,
      subtotal,
      currency,
    };
  }

  getItems(cart: Cart): CartItem[] {
    return [...cart.items];
  }

  hasItem(cart: Cart, productId: string): boolean {
    return cart.items.some((item) => item.productId === productId);
  }

  getItemQuantity(cart: Cart, productId: string): number {
    const item = cart.items.find((item) => item.productId === productId);
    return item?.quantity ?? 0;
  }

  on(eventType: CartEventType, handler: (event: CartEvent) => Promise<void> | void): void {
    this.eventBus?.subscribe(eventType, handler);
  }

  off(eventType: CartEventType, handler: (event: CartEvent) => Promise<void> | void): void {
    this.eventBus?.unsubscribe(eventType, handler);
  }

  private async getOrCreateCart(cartId: string): Promise<Cart> {
    let cart = await this.storage.get(cartId);
    if (!cart) {
      cart = await this.createCart(cartId);
    }
    return cart;
  }

  private async getCartOrThrow(cartId: string): Promise<Cart> {
    const cart = await this.storage.get(cartId);
    if (!cart) {
      throw new Error(`Cart with id ${cartId} not found`);
    }
    return cart;
  }

  private validateAddItem(cart: Cart, input: AddItemInput): void {
    if (input.quantity <= 0) {
      throw new Error('Quantity must be greater than 0');
    }
    if (input.price < 0) {
      throw new Error('Price cannot be negative');
    }
    if (!input.name || !input.name.trim()) {
      throw new Error('Product name is required');
    }
    if (!input.currency || !input.currency.trim()) {
      throw new Error('Currency is required');
    }
  }

  private validateQuantity(quantity: number): void {
    if (quantity < 0) {
      throw new Error('Quantity cannot be negative');
    }
    if (quantity > this.maxQuantityPerItem) {
      throw new Error(`Maximum quantity per item (${this.maxQuantityPerItem}) exceeded`);
    }
  }

  private async emitEvent(event: CartEvent): Promise<void> {
    if (this.eventBus) {
      await this.eventBus.publish(event);
    }
  }
}

export function createCartService(options: CartOptions): CartService {
  return new CartService(options);
}

export function createDefaultCartService(): CartService {
  return new CartService({
    storage: new InMemoryStorage(),
    eventBus: new InMemoryEventBus(),
  });
}

export * from './types';
export * from './event-bus';
export * from './storage';
export * from './cart';

import {
  CartService,
  createDefaultCartService,
  InMemoryStorage,
  InMemoryEventBus,
  FileStorage,
  Cart,
  CartItem,
} from '../src';

async function basicExample(): Promise<void> {
  console.log('=== Basic Shopping Cart Example ===\n');

  const cartService = createDefaultCartService();
  const cartId = 'user-123-cart';

  console.log('1. Adding items to cart...');
  await cartService.addItem(cartId, {
    productId: 'prod-001',
    name: 'Wireless Headphones',
    price: 149.99,
    currency: 'USD',
    quantity: 1,
  });

  await cartService.addItem(cartId, {
    productId: 'prod-002',
    name: 'Phone Case',
    price: 24.99,
    currency: 'USD',
    quantity: 2,
  });

  await cartService.addItem(cartId, {
    productId: 'prod-003',
    name: 'USB-C Cable',
    price: 12.99,
    currency: 'USD',
    quantity: 3,
  });

  console.log('2. Getting cart...');
  const cart = await cartService.getCart(cartId);
  if (cart) {
    console.log(`   Cart ID: ${cart.id}`);
    console.log(`   Items: ${cart.items.length}`);
    console.log(`   Created: ${cart.createdAt.toISOString()}`);
    console.log(`   Updated: ${cart.updatedAt.toISOString()}`);
  }

  console.log('\n3. Cart summary...');
  if (cart) {
    const summary = cartService.getSummary(cart);
    console.log(`   Item count: ${summary.itemCount}`);
    console.log(`   Total quantity: ${summary.totalQuantity}`);
    console.log(`   Subtotal: ${summary.currency} ${summary.subtotal.toFixed(2)}`);
  }

  console.log('\n4. Updating item quantity...');
  await cartService.updateItem(cartId, {
    productId: 'prod-002',
    quantity: 5,
  });

  const updatedCart = await cartService.getCart(cartId);
  if (updatedCart) {
    const summary = cartService.getSummary(updatedCart);
    console.log(`   Updated subtotal: ${summary.currency} ${summary.subtotal.toFixed(2)}`);
  }

  console.log('\n5. Removing item...');
  await cartService.removeItem(cartId, 'prod-003');

  const cartAfterRemove = await cartService.getCart(cartId);
  if (cartAfterRemove) {
    const summary = cartService.getSummary(cartAfterRemove);
    console.log(`   Items after removal: ${summary.itemCount}`);
    console.log(`   Subtotal: ${summary.currency} ${summary.subtotal.toFixed(2)}`);
  }

  console.log('\n6. Checking item existence...');
  if (cartAfterRemove) {
    console.log(`   Has prod-001: ${cartService.hasItem(cartAfterRemove, 'prod-001')}`);
    console.log(`   Has prod-003: ${cartService.hasItem(cartAfterRemove, 'prod-003')}`);
    console.log(`   Quantity of prod-001: ${cartService.getItemQuantity(cartAfterRemove, 'prod-001')}`);
  }

  console.log('\n7. Clearing cart...');
  await cartService.clearCart(cartId);

  const clearedCart = await cartService.getCart(cartId);
  if (clearedCart) {
    console.log(`   Items after clear: ${clearedCart.items.length}`);
  }

  console.log('\n=== Example completed ===');
}

async function eventExample(): Promise<void> {
  console.log('\n=== Event-Driven Example ===\n');

  const storage = new InMemoryStorage();
  const eventBus = new InMemoryEventBus();
  const cartService = new CartService({ storage, eventBus });
  const cartId = 'event-cart-456';

  eventBus.subscribe('item.added', async (event) => {
    console.log(`[EVENT] Item added: ${JSON.stringify(event.payload)}`);
  });

  eventBus.subscribe('item.updated', async (event) => {
    console.log(`[EVENT] Item updated: ${JSON.stringify(event.payload)}`);
  });

  eventBus.subscribe('item.removed', async (event) => {
    console.log(`[EVENT] Item removed: ${JSON.stringify(event.payload)}`);
  });

  eventBus.subscribe('cart.updated', async (event) => {
    console.log(`[EVENT] Cart updated, items: ${(event.payload as { cart: Cart }).cart.items.length}`);
  });

  eventBus.subscribe('cart.cleared', async (event) => {
    console.log(`[EVENT] Cart cleared: ${JSON.stringify(event.payload)}`);
  });

  console.log('Adding items with event listeners...');
  await cartService.addItem(cartId, {
    productId: 'prod-A',
    name: 'Product A',
    price: 10.00,
    currency: 'USD',
    quantity: 2,
  });

  await cartService.addItem(cartId, {
    productId: 'prod-B',
    name: 'Product B',
    price: 20.00,
    currency: 'USD',
    quantity: 1,
  });

  console.log('\nUpdating quantity...');
  await cartService.updateItem(cartId, {
    productId: 'prod-A',
    quantity: 5,
  });

  console.log('\nRemoving item...');
  await cartService.removeItem(cartId, 'prod-B');

  console.log('\nClearing cart...');
  await cartService.clearCart(cartId);

  console.log('\n=== Event example completed ===');
}

async function persistenceExample(): Promise<void> {
  console.log('\n=== File Persistence Example ===\n');

  const fileStorage = new FileStorage('./data/carts');
  const cartService = new CartService({ storage: fileStorage });
  const cartId = 'persistent-cart-789';

  console.log('Adding items to persistent cart...');
  await cartService.addItem(cartId, {
    productId: 'persist-1',
    name: 'Persistent Item 1',
    price: 99.99,
    currency: 'EUR',
    quantity: 1,
  });

  await cartService.addItem(cartId, {
    productId: 'persist-2',
    name: 'Persistent Item 2',
    price: 49.99,
    currency: 'EUR',
    quantity: 2,
  });

  const cart = await cartService.getCart(cartId);
  if (cart) {
    const summary = cartService.getSummary(cart);
    console.log(`Cart saved with ${summary.itemCount} items, total: ${summary.currency} ${summary.subtotal.toFixed(2)}`);
  }

  console.log('\nSimulating app restart - creating new service instance...');
  const newFileStorage = new FileStorage('./data/carts');
  const newCartService = new CartService({ storage: newFileStorage });

  const restoredCart = await newCartService.getCart(cartId);
  if (restoredCart) {
    const summary = newCartService.getSummary(restoredCart);
    console.log(`Cart restored with ${summary.itemCount} items, total: ${summary.currency} ${summary.subtotal.toFixed(2)}`);
    console.log('Items:');
    restoredCart.items.forEach((item) => {
      console.log(`  - ${item.name} x${item.quantity} @ ${item.currency} ${item.price}`);
    });
  }

  console.log('\n=== Persistence example completed ===');
}

async function advancedExample(): Promise<void> {
  console.log('\n=== Advanced Configuration Example ===\n');

  const storage = new InMemoryStorage();
  const cartService = new CartService({
    storage,
    maxItems: 3,
    maxQuantityPerItem: 10,
  });
  const cartId = 'advanced-cart';

  console.log('Testing max items limit (3)...');
  await cartService.addItem(cartId, {
    productId: 'p1', name: 'Item 1', price: 10, currency: 'USD', quantity: 1,
  });
  await cartService.addItem(cartId, {
    productId: 'p2', name: 'Item 2', price: 10, currency: 'USD', quantity: 1,
  });
  await cartService.addItem(cartId, {
    productId: 'p3', name: 'Item 3', price: 10, currency: 'USD', quantity: 1,
  });

  try {
    await cartService.addItem(cartId, {
      productId: 'p4', name: 'Item 4', price: 10, currency: 'USD', quantity: 1,
    });
    console.log('ERROR: Should have thrown!');
  } catch (error) {
    console.log(`   Correctly rejected: ${(error as Error).message}`);
  }

  console.log('\nTesting max quantity per item (10)...');
  try {
    await cartService.updateItem(cartId, { productId: 'p1', quantity: 15 });
    console.log('ERROR: Should have thrown!');
  } catch (error) {
    console.log(`   Correctly rejected: ${(error as Error).message}`);
  }

  await cartService.updateItem(cartId, { productId: 'p1', quantity: 10 });
  console.log('   Quantity 10 accepted');

  console.log('\n=== Advanced example completed ===');
}

async function main(): Promise<void> {
  await basicExample();
  await eventExample();
  await persistenceExample();
  await advancedExample();
}

